p:=0;SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(8*10^9);Alarm(800);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");if p eq 0 then k<zet>:=CyclotomicField(3);else k:=GF(p);end if;X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F)eq 10;B:=BaseField(F);E:=EllipticCurve(X`_E);P:=E!X`_P;Q:=E!X`_Q;print "M318_CUSP_MODEL_FIELD_READY",p,Cputime(tt);
function Units(E,P,Q)ai:=aInvariants(E);fs:=[ai[3],ai[1]^3-27*ai[3]];for j in[1..9]do for b in[0..2]do R:=j*Q+b*P;fs cat:=[R[1],R[2]];end for;R:=j*Q;S:=R+P;Append(~fs,R[1]-S[1]);end for;return fs;end function;
old:=eval Read(root cat "paired_p7_group_data.m");sigs:=old[2];ds:=old[3];u:=F!B.1;pts:=&cat[Zeros(u-F!a):a in[k!0,k!-1,zet,zet^2]]cat Poles(u);pts:=Setseq(Seqset(pts));jf:=mp(jInvariant(E));pts:=[P:P in pts|Degree(P)eq 1 and Valuation(jf,P)lt 0];assert #pts eq 18;fs:=Units(E,P,Q);groups:=AssociativeArray();for c in pts do sig:=[Valuation(mp(f),c):f in fs];assert sig in sigs and ds[Index(sigs,sig)]eq 1 and not IsDefined(groups,sig);groups[sig]:=c;end for;assert #Keys(groups)eq 18;print "M318_GLOBAL_RATIONAL_CUSPS_READY",#pts,Cputime(tt);
function EC(a)if p eq 0 then return Eltseq(k!a);else return Integers()!(k!a);end if;end function;
function ER(f)return [[EC(c):c in Coefficients(Numerator(f))],[EC(c):c in Coefficients(Denominator(f))]];end function;function EF(f)return [ER(c):c in Eltseq(F!f)];end function;function EP(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b>eq Ideal(P);return[*Degree(P),IsFinite(P)select 1 else 0,[EF(a),EF(b)]*];end function;
pds:=[* *];for i in[1..24]do if ds[i]eq 1 then Append(~pds,[*EP(groups[sigs[i]])*]);else Append(~pds,[* *]);end if;end for;Write(root cat "global_cusp_model_char0_rational.m",Sprint([*0,[ER(c):c in Coefficients(DefiningPolynomial(F))],pds,sigs,ds,[EF(mp(f)):f in X`_coordinates],1*]):Overwrite:=true);print "D31B_M318_GLOBAL_RATIONAL_CUSP_MODEL_COMPLETE",18,Cputime(tt);quit;
